logo=(ROOT/'frontend/assets/logo.svg').read_text()
chart='data:image/png;base64,'+base64.b64encode((ROOT/'reports/daily_risk_calibration_current_reliability.png').read_bytes()).decode()
pages=[]
def page(title,body,kicker='FIRESPOT / OPIS PROJEKTU'):
 n=len(pages)+1
 pages.append(f'<section class="page"><div class="kicker">{kicker}</div><h1>{title}</h1>{body}<footer><span>FireSpot · 15 listopada 2026</span><span>{n:02d}</span></footer></section>')
page('FireSpot',f'''<div class="cover-mark">{logo}</div><p class="lead">Jedna mapa obserwacji satelitarnych,<br>historii pożarów i prognoz ML + fizyka.</p>
<p class="intro">Projekt przygotowany na NASA Space Apps Challenge 2026. Łączy dane MODIS i VIIRS, aby porównywać aktywność pożarową między latami, wykrywać nietypowe zdarzenia i badać możliwe kierunki rozprzestrzeniania się ognia.</p>
<div class="numbers"><div><b>2</b><span>rodziny sensorów:<br>MODIS i VIIRS</span></div><div><b>1–3 dni</b><span>horyzont dziennej<br>prognozy ML</span></div><div><b>5</b><span>krajów z w pełni<br>przetworzonym archiwum</span></div></div>
<h2>Dla kogo?</h2><p>Dla badaczy, osób zarządzających terenem, analityków ryzyka i zespołów monitorujących sytuację pożarową. Narzędzie porządkuje obserwacje i wspiera eksplorację scenariuszy.</p>
<div class="note">Prototyp badawczy. Nie ma walidacji pozwalającej używać go samodzielnie do decyzji o ewakuacji, wysyłaniu służb czy wycenie szkód.</div>
<p class="small">Dokument opisuje działającą aplikację, sposób przetwarzania danych, wyniki eksperymentów i aktualne ograniczenia. Wyniki są pomiarami projektu, a nie deklaracją ogólnej skuteczności.</p>''','NASA SPACE APPS CHALLENGE 2026')
page('Problem i dane','''<h2>Dlaczego samo zliczanie punktów nie wystarcza?</h2><p>MODIS obserwuje pożary w pikselach o nominalnym rozmiarze około 1 km, a VIIRS około 375 m. Ten sam pożar może więc dawać inną liczbę wykryć i inny obraz powierzchni. Zmiana sensora może stworzyć sztuczny skok w wieloletnim szeregu danych.</p>
<p>FireSpot sprowadza obserwacje do wspólnej siatki 0,05° — około 5,5 km w kierunku północ–południe. Rozróżnia detekcję satelitarną, komórkę z aktywnością i przybliżoną grupę pożarów.</p>
<table><tr><th>Źródło</th><th>Rola w projekcie</th></tr><tr><td>NASA FIRMS · MODIS / VIIRS</td><td>Archiwum i bieżące detekcje, czas obserwacji, moc radiacyjna FRP, geometria piksela.</td></tr><tr><td>Open-Meteo / NOAA GFS</td><td>Wiatr, temperatura, wilgotność i opady; warunki zmieniają się w czasie symulacji.</td></tr><tr><td>ESA WorldCover / Copernicus DEM</td><td>Przybliżenie paliwa roślinnego, obszary niepalne, wysokość i nachylenie terenu.</td></tr><tr><td>Sentinel-2 / OpenStreetMap</td><td>Wskaźniki wilgotności roślinności oraz heurystyczne bariery: drogi i cieki wodne.</td></tr><tr><td>Orbity / GOES / RainViewer</td><td>Pozycje i przeloty satelitów, opcjonalne obserwacje geostacjonarne, warstwa opadów.</td></tr></table>
<h2>Zakres danych</h2><p>Pobrano archiwa dla 176 krajów. Pełne przetwarzanie, bazowe kalendarze i główne eksperymenty obejmują Brazylię, Australię, Indie, USA i Kanadę. Szeregi harmonizowane dla tych obszarów sięgają lat 2000–2025; dane sprzed VIIRS są rekonstrukcją.</p><div class="note">Brak detekcji nie oznacza braku ognia. Chmury, dym, pora przelotu i rozdzielczość ograniczają obserwacje.</div>''')
page('Co można zrobić w aplikacji?','''<div class="feature"><h2>Monitoring</h2><p>Przegląd bieżących wykryć ognia, analiza wybranego obszaru, mapa i glob, pozycje satelitów MODIS/VIIRS oraz kontekst aktywności. Czerwone punkty są widoczne w Monitoringu, Prognozie i Alertach. Globalna warstwa pokazuje 250 najsilniejszych wykryć, więc nie jest kompletnym spisem wszystkich pożarów.</p></div>
<div class="feature"><h2>Prognoza</h2><p>Wybór pożaru i czasu inicjalizacji, horyzont do 72 godzin oraz wspólna oś czasu ML + fizyka. Odtwarzanie, przewijanie, zmiana kroku i prędkości. Dzienne wskazania ML są odróżnione od drobniejszych klatek symulacji fizycznej.</p></div>
<div class="feature"><h2>Historia</h2><p>Rysowanie prostokąta na mapie, wybór obszaru, kalendarz tygodniowej aktywności, porównania lat, sensorów i odchyleń od sezonowej normy. Domyślną miarą są komórki MODIS, aby unikać skoku wynikającego z mieszania sensorów.</p></div>
<div class="feature"><h2>Alerty</h2><p>Regiony o aktywności wyższej od typowej dla danego tygodnia. Poziomy watch, warning i critical bazują na odchyleniu od historycznej normy; nie są prognozą potwierdzonego zagrożenia.</p></div>
<div class="feature"><h2>Odtwarzanie historyczne</h2><p>Najpierw prognoza ograniczona do danych dostępnych przy inicjalizacji, później odsłonięcie rzeczywistych detekcji i porównanie. Sześć zapisanych zdarzeń demonstracyjnych działa z lokalnego cache. Narysowanie prostokąta ustawia środek odtworzenia własnego; model nie symuluje dowolnego wielokąta.</p></div>
<h2>Dodatkowe narzędzia</h2><p>Następny użyteczny przelot, obszary niedostatecznie obserwowane, hipotetyczne zmiany pogody, ekspozycja infrastruktury i ludności, podsumowanie incydentu oraz eksporty GeoJSON, CSV, JSON i CAP.</p><p class="small">Ekspozycja oznacza obiekty znajdujące się w symulowanym zasięgu. Nie jest oszacowaniem szkód, ofiar ani wartości pieniężnych. Interfejs ma język polski i angielski oraz jasny i ciemny motyw.</p>''')
page('Jak powstaje prognoza?','''<div class="step"><b>01 / Stan początkowy</b><p>System wybiera pobliskie wykrycia i stosuje odcięcie czasowe. Obserwacje późniejsze niż inicjalizacja nie mogą stać się wejściem prognozy. Tryb live dysponuje skróconą, siedmiodniową historią.</p></div>
<div class="step"><b>02 / Dzienne wskazania ML</b><p>XGBoost wykorzystuje m.in. odległość od frontu, aktywność w sąsiedztwie, historię komórki, FRP, sezon i dostępne warunki pogodowe. Mały blender łączy wynik ML z cechami fizycznego rozprzestrzeniania.</p></div>
<div class="step"><b>03 / Symulacja fizyczna</b><p>Model Rothermela i klasy paliwa Andersona określają tempo rozwoju frontu. Symulacja uwzględnia wiatr, wilgotność paliwa, opady, nachylenie terenu i dostępne bariery. Front porusza się po siatce za pomocą algorytmu minimalnego czasu dotarcia.</p></div>
<div class="step"><b>04 / Wspólny wynik</b><p>Obie części muszą zakończyć obliczenia. Dopiero wtedy aplikacja pokazuje gotowe klatki i uruchamia odtwarzanie. Model nie trenuje się po każdej animacji; uczenie i kalibracja są osobnymi eksperymentami offline.</p></div>
<h2>Co oznaczają kolory?</h2><p>Kolory obrysu pokazują czas dotarcia symulowanego ognia. Dzienne komórki są wskazaniami modelu. Kolor nie jest procentem pewności, a warianty niskiego i wysokiego zasięgu są scenariuszami pogodowymi, nie przedziałem ufności.</p><div class="note">Blender był dopasowany z prostszą wersją fizyki niż bogatsza animacja godzinowa. Nie zakładamy, że dokładniejsze warstwy wizualnej symulacji automatycznie poprawiają jakość wytrenowanego blendera.</div>''')
page('Co potwierdzają testy?','''<p>Najważniejsze wyniki pochodzą z testów na późniejszych latach. Wartości opisują konkretne zbiory danych i miary; nie są procentową pewnością każdego nowego zdarzenia.</p>
<table><tr><th>ML + fizyka</th><th>2024</th><th>2025</th></tr><tr><td>Dzień 1 · dopasowanie z tolerancją około 5 km</td><td>58,68%</td><td>56,82%</td></tr><tr><td>Dzień 3 · taka sama tolerancja</td><td>76,07%</td><td>73,48%</td></tr><tr><td>Dzień 3 · dokładne pokrycie komórek, IoU</td><td>30,72%</td><td>28,31%</td></tr></table>
<p class="small">Po 100 testowych przypadków na rok. Wynik z tolerancją przestrzenną nie jest accuracy ani prawdopodobieństwem sukcesu. Połączenie ML + fizyka nie wykazało przewagi nad równie dostrojonym samym ML. Cel ponad 70% w dniu 1 pozostaje niespełniony.</p>
<h2>Pozostałe części projektu</h2><table><tr><th>Obszar</th><th>Wynik i zakres</th></tr><tr><td>Rekonstrukcja MODIS → VIIRS</td><td>IoU 0,248 wobec 0,177 dla surowego MODIS; test 2021–2025. Nie odzyskuje małych pożarów niewidzianych przez MODIS.</td></tr><tr><td>Korekta geometrii skanowania</td><td>Przy brzegu pasa obserwacji: 1,339 → 1,007 klastrów MODIS na pojedynczy pożar VIIRS. Koszt: częstsze łączenie bliskich, odrębnych pożarów.</td></tr><tr><td>Rutynowe wypalanie czy anomalia?</td><td>10 poprawnych klasyfikacji na 12 niezależnych zdarzeń. Mała próba; wynik nie uzasadnia automatycznych decyzji.</td></tr><tr><td>Fizyka z krajobrazem</td><td>Walidacja na 20 pożarach. Warstwy krajobrazowe ograniczają wcześniejsze przeszacowania, ale błędy pozostają duże.</td></tr><tr><td>Alerty anomalii live</td><td>Funkcjonalne API i interfejs. Brak badania czasu wyprzedzenia i odsetka fałszywych alarmów.</td></tr></table>
<div class="note">Ocena na historycznej pogodzie obserwowanej jest optymistyczna względem pracy z prawdziwą prognozą pogody wydaną wcześniej.</div>''')
page('Kalibracja dziennego ryzyka',f'''<p>Nowy eksperyment dopasowuje prawdopodobieństwa, a nie prędkość animacji. Kalibrowane jest ryzyko <b>nowej detekcji w komórce do końca dnia 1, 2 i 3</b>, z zachowaniem narastania ryzyka w czasie.</p>
<h2>Wariant bieżącego modelu</h2><p>45 przypadków do kalibracji z pierwszej części 2025 r., 51 późniejszych przypadków do testu. Czerwiec stanowi przerwę między zbiorami. Model bazowy pozostaje zamrożony; parametry kalibracji zapisano przed oceną tego podziału.</p>
<table><tr><th>Horyzont</th><th>Średni błąd kalibracji ECE · przed → po</th></tr><tr><td>Do końca dnia 1</td><td>0,91% → 0,55%</td></tr><tr><td>Do końca dnia 2</td><td>1,46% → 1,00%</td></tr><tr><td>Do końca dnia 3</td><td>1,48% → 0,94%</td></tr></table>
<img class="chart" src="{chart}" alt="Krzywe kalibracji dla trzech horyzontów"/>
<p>ECE jest średnią rozbieżnością między przewidywanym ryzykiem a częstością obserwacji w grupach. <b>Nie oznacza to pewności 99% ani błędu pojedynczej prognozy poniżej 1%.</b></p>
<p>Poprawa ogólnego wyniku Brier jest mała i statystycznie niepewna; w dniu 1 wynik jest minimalnie gorszy. Warianty zapisano jako badawcze i nie zastępują obecnej prognozy live.</p><p class="small">To ponowne wykorzystanie benchmarku historycznego, nie świeży test prospektywny. Nie walidowano tych procentów dla Sudanu Południowego ani skróconej historii live.</p>''')
page('Architektura i wydajność','''<div class="flow">Dane satelitarne i środowiskowe<br><span>↓</span><br>Agregacja · harmonizacja · lokalny cache<br><span>↓</span><br>Modele ML + fizyka<br><span>↓</span><br>FastAPI → aplikacja mapowa → eksport</div>
<h2>Technologia</h2><p>Backend Python/FastAPI udostępnia API i statyczny frontend z jednego adresu. Mapa korzysta z Leaflet, glob z globe.gl. Główne modele są oparte na XGBoost i obliczeniach NumPy/SciPy; rastry odczytywane są z użyciem narzędzi geoprzestrzennych. Indeks pożarów jest mapowany z dysku do pamięci.</p>
<h2>Gotowy wynik przed animacją</h2><p>Po wyborze punktu dzienna prognoza i godzinowa symulacja pracują równolegle. Odtwarzanie korzysta z gotowych klatek w przeglądarce. Identyczne zapytania oraz dane źródłowe są przechowywane w cache; proces przygotowujący popularne obszary ogrzewa do 72 godzin warunków.</p>
<table><tr><th>Ostatni pomiar pełnej prognozy 72 h</th><th>Czas</th></tr><tr><td>Brazylia · ponowne zbudowanie warstwy Sentinel</td><td>21,6 s</td></tr><tr><td>Dwa równoczesne zapytania · Brazylia / Indie</td><td>22,3 s / 24,6 s</td></tr></table>
<p class="small">Każdy wynik zawierał dzienne wskazania i 73 klatki fizyki. Część źródeł była już w cache; nie jest to gwarancja czasu dla wszystkich miejsc i awarii dostawców.</p>
<p>Brakujące bariery OpenStreetMap są opcjonalne i przygotowywane w tle; ich zasięg jest ujawniany w wyniku. Pogoda, paliwo, teren i przetwarzanie roślinności pozostają częścią prognozy. Nie dodano pozornie szybkiej odpowiedzi zastępującej niedokończony model.</p>
<h2>Uruchomienie lokalne</h2><pre>.venv/bin/python -m uvicorn backend.app:app\n  --host 0.0.0.0 --port 8080</pre><p class="small">Potrzebne są gotowe modele i cache. Stan ładowania: /health; dokumentacja API: /docs. Przygotowanie danych i trening są osobnym, cięższym procesem.</p>''')
page('Ograniczenia i dalszy rozwój','''<h2>Co trzeba brać pod uwagę?</h2><ul><li>Detekcje satelitarne są niepełną prawdą odniesienia. Chmury, dym i odstępy między przelotami pozostawiają luki.</li><li>Archiwum jest szerokie geograficznie, ale główna walidacja i pełne przetwarzanie obejmują pięć krajów. Wyników nie wolno automatycznie przenosić na inne regiony.</li><li>Model fizyczny upraszcza paliwo i jego wilgotność. Nie opisuje pełnego wpływu działań gaśniczych ani wszystkich mechanizmów przenoszenia ognia.</li><li>Scenariusze pogodowe nie są statystycznymi przedziałami ufności. Punkty detekcji nie są dokładną granicą pożaru.</li><li>Dane historyczne sprzed VIIRS są rekonstrukcją o dodatkowej niepewności. Wyniki harmonizacji mogą różnić się między krajami.</li><li>Dane zewnętrzne mogą być niedostępne lub wolne. Nie ma uniwersalnej gwarancji zakończenia każdego zimnego zapytania poniżej minuty.</li></ul>
<h2>Najważniejsze następne kroki</h2><ol><li>Sprawdzić ryzyko i kalibrację na nowych sezonach oraz niezależnych zdarzeniach live.</li><li>Dopasować i ocenić blender wykorzystujący bogatszą fizykę krajobrazu oraz prognozy pogody dostępne w chwili wydania.</li><li>Rozszerzać pełne przetwarzanie archiwum poza pięć krajów i poprawiać pokrycie danych.</li><li>Kontynuować testy użyteczności wspólnych kontrolek mapy, obsługi telefonów i eksportów dla różnych sposobów pracy.</li></ol>
<h2>Dokumentacja wyników w repozytorium</h2><p class="small">docs/MODEL_CARD.md · docs/DATA_SOURCES_AND_LICENSES.md · docs/DEMO_SCRIPT.md · reports/FORECAST_SPEED.md · reports/DAILY_RISK_CALIBRATION.md · reports/CLAUDE_CONTINUATION.md · reports/ensemble_ab_2024.json · reports/ensemble_ab_2025.json</p>
<div class="note">Siła projektu leży w połączeniu obserwacji, harmonizacji, historii i modelowania w jednym narzędziu — z jawnym rozróżnieniem między danymi, scenariuszem i potwierdzonym wynikiem walidacji.</div>''')
html='''<!doctype html><html lang="pl"><meta charset="utf-8"><title>FireSpot — opis projektu</title><style>
@page{size:A4;margin:0}*{box-sizing:border-box}body{margin:0;color:#1d2b34;font:10.6pt/1.46 "DejaVu Sans",sans-serif;background:#fff}.page{width:210mm;height:297mm;padding:18mm 18mm 23mm;break-after:page;position:relative}.page:last-child{break-after:auto}.kicker{font-size:8pt;letter-spacing:1.4px;font-weight:700;color:#145c64;margin-bottom:7mm}h1{font-size:27pt;line-height:1.15;letter-spacing:-.7px;margin:0 0 7mm}h2{font-size:13pt;line-height:1.2;margin:5mm 0 2mm}p{margin:0 0 3mm}.small{font-size:8.7pt;line-height:1.4;color:#526570}.lead{font-size:21pt;line-height:1.35;margin:10mm 0 6mm;max-width:145mm}.intro{font-size:12pt;line-height:1.55;max-width:150mm}.cover-mark{position:absolute;right:18mm;top:17mm;width:12mm;height:19mm}.cover-mark svg{width:100%;height:100%}.numbers{display:flex;gap:12mm;padding:7mm 0;margin:5mm 0;border-top:1px solid #ccd9dc;border-bottom:1px solid #ccd9dc}.numbers b{display:block;font-size:24pt;color:#145c64;letter-spacing:-1px}.numbers span{font-size:9pt}.note{padding:3.5mm 4mm;background:#edf4f3;border-left:3px solid #145c64;font-size:9.3pt;margin:4mm 0}.feature{padding-bottom:2mm;border-bottom:1px solid #dce3e6}.feature h2{margin-top:4mm}.step b{font-size:11pt;color:#145c64}.step{margin-bottom:4mm}table{border-collapse:collapse;width:100%;font-size:9.2pt;margin:4mm 0}th{text-align:left;color:#145c64;background:#edf4f3;font-size:8.8pt}td,th{padding:3mm;border-bottom:1px solid #dce3e6;vertical-align:top}td:first-child{width:43%}tr{break-inside:avoid}.chart{display:block;width:100%;margin:4mm 0}.flow{text-align:center;background:#edf4f3;padding:3mm;font-size:10.5pt;font-weight:600;line-height:1.2}.flow span{color:#145c64}pre{white-space:pre-wrap;background:#f0f3f4;padding:3mm;font:9pt/1.5 "DejaVu Sans Mono",monospace}ul,ol{padding-left:5mm;margin:2mm 0 4mm}li{padding-left:1mm;margin-bottom:2mm}footer{position:absolute;left:18mm;right:18mm;bottom:10mm;border-top:1px solid #dce3e6;padding-top:3mm;display:flex;justify-content:space-between;font-size:8pt;color:#63717a}
</style><body>'''+''.join(pages)+'</body></html>'
out=ROOT/'reports/FireSpot_opis_projektu.html';out.write_text(html)
async def main():
 async with async_playwright() as p:
  b=await p.chromium.launch(executable_path='/home/klon/.cache/ms-playwright/chromium-1254/chrome-linux64/chrome',args=['--no-sandbox'])
  pg=await b.new_page();await pg.goto(out.as_uri());await pg.emulate_media(media='print')
  overflow=await pg.evaluate('''()=>[...document.querySelectorAll('.page')].map((p,i)=>({page:i+1,overflow:p.scrollHeight>p.clientHeight+1,last:[...p.children].filter(x=>x.tagName!=='FOOTER'&&!x.classList.contains('cover-mark')).at(-1).getBoundingClientRect().bottom,footer:p.querySelector('footer').getBoundingClientRect().top})).filter(x=>x.overflow||x.last>x.footer-10)''')
  if overflow:raise RuntimeError(str(overflow))
  await pg.pdf(path=str(ROOT/'reports/FireSpot_opis_projektu.pdf'),print_background=True,prefer_css_page_size=True)
  await pg.screenshot(path=str(ROOT/'reports/FireSpot_opis_projektu_preview.png'),clip={'x':0,'y':0,'width':794,'height':1123})
  await b.close()
 print(ROOT/'reports/FireSpot_opis_projektu.pdf')
if __name__ == '__main__':
 asyncio.run(main())
